head.script:
scwin.onpageload = function() {
    scwin.itemCodeMap = {
        "01": "기획/전략 수립",
        "02": "화면 설계 및 기획",
        "03": "UI/UX 컴포넌트 개발",
        "04": "백엔드 API 연동",
        "05": "품질 테스트 및 QA",
        "06": "서버 배포 및 모니터링",
        "07": "사용자 매뉴얼 작성"
    };
};

/**
 * [포맷터] 담당 업무 다중 선택 코드 라벨 변환 및 <br/> 개행
 */
scwin.fn_formatMultiCheck = function(data) {
    if (!data || typeof data !== "string" || data.trim() === "") {
        if (window.parent && window.parent.scwin && window.parent.scwin._isExcelDownloading) {
            return "";
        }
        return '<span style="color:#94a3b8; font-style:italic;">(선택 없음)</span>';
    }

    var codeList = data.split(",");
    var labelList = [];
    for (var i = 0; i < codeList.length; i++) {
        var code = codeList[i].trim();
        if (code !== "") {
            var label = (scwin.itemCodeMap && scwin.itemCodeMap[code]) ? scwin.itemCodeMap[code] : code;
            labelList.push(label);
        }
    }

    if (labelList.length === 0) {
        return '<span style="color:#94a3b8; font-style:italic;">(선택 없음)</span>';
    }
    return labelList.join("<br/>");
};

/**
 * [포맷터] 담당자 컬럼 포맷터
 */
scwin.fn_formatUserName = function(data) {
    if (!data || typeof data !== "string" || data.trim() === "") {
        return '<span style="color:#94a3b8; font-style:italic;">클릭하여 입력</span>';
    }
    return data;
};

/**
 * [DOM 헬퍼] 그리드 TD Element 취득
 */
scwin.fn_getGridCellDom = function(gridObj, row, col) {
    var gridId = (typeof gridObj.getID === "function") ? gridObj.getID() : gridObj.id;
    var cellDom = document.getElementById(gridId + "_cell_" + row + "_" + col);
    if (cellDom) return cellDom;

    var evt = window.event;
    if (evt && evt.target) {
        var td = evt.target.closest ? evt.target.closest("td") : null;
        if (td) return td;
    }
    if (typeof gridObj.getCellElement === "function") {
        return gridObj.getCellElement(row, col);
    }
    return null;
};

/**
 * [행 추가] 메인 그리드 신규 행 삽입
 */
scwin.btn_addRow_onclick = function() {
    var newRowIdx = dlt_sample.insertRow();
    var total = dlt_sample.getTotalRow();
    dlt_sample.setCellData(newRowIdx, "seq", total);
    dlt_sample.setCellData(newRowIdx, "userName", "");
    dlt_sample.setCellData(newRowIdx, "taskCodes", "");
    dlt_sample.setCellData(newRowIdx, "remark", "신규 행");

    if (typeof grd_main.setFocusedCell === "function") {
        grd_main.setFocusedCell(newRowIdx, "userName", true);
    }
};

/**
 * [셀 클릭] 담당 업무 또는 담당자 클릭 이벤트
 */
scwin.grd_main_oncellclick = function(row, col) {
    var colId = grd_main.getColumnID(col);

    if (colId === "userName") {
        setTimeout(function() {
            var cellDom = scwin.fn_getGridCellDom(grd_main, row, col);
            if (cellDom) {
                var input = cellDom.querySelector("input") || cellDom.querySelector(".w2grid_input");
                if (input) {
                    input.placeholder = "입력후 엔터";
                    input.focus();
                }
            }
        }, 30);
        return;
    }

    if (colId !== "taskCodes") return;

    var cellDom = scwin.fn_getGridCellDom(grd_main, row, col);
    if (!cellDom) return;

    var rawValue = dlt_sample.getCellData(row, colId) || "";
    var selectedCodes = rawValue ? rawValue.split(",").map(function(c) { return c.trim(); }) : [];
    scwin.fn_openMultiCheckLayer(cellDom, row, colId, selectedCodes, dlt_sample);
};

/**
 * [엔터 키] 담당자 입력란 엔터 시 담당자 검색 모달 호출
 */
scwin.grd_main_oneditkeydown = function(row, col, keyCode, e) {
    var colId = grd_main.getColumnID(col);
    if (colId === "userName" && keyCode === 13) {
        var cellDom = scwin.fn_getGridCellDom(grd_main, row, col);
        var input = cellDom ? (cellDom.querySelector("input") || cellDom.querySelector(".w2grid_input")) : null;
        var keyword = input ? input.value : (dlt_sample.getCellData(row, "userName") || "");
        scwin.fn_openManagerSearch(row, keyword);
    }
};

/**
 * [포커스 아웃] placeholder 복원
 */
scwin.grd_main_oneditblur = function(row, col) {
    var colId = grd_main.getColumnID(col);
    if (colId === "userName") {
        var cellDom = scwin.fn_getGridCellDom(grd_main, row, col);
        if (cellDom) {
            var input = cellDom.querySelector("input") || cellDom.querySelector(".w2grid_input");
            if (input && !input.value) {
                input.placeholder = "클릭하여 입력";
            }
        }
    }
};

// 임직원 샘플 데이터셋 (담당자 검색용)
scwin.managerList = [
    { empId: "E1001", name: "홍길동", title: "수석", dept: "프론트엔드팀", email: "gdhong@example.com" },
    { empId: "E1002", name: "이순신", title: "책임", dept: "클라우드인프라팀", email: "sslee@example.com" },
    { empId: "E1003", name: "강감찬", title: "선임", dept: "품질보증QA팀", email: "gckang@example.com" },
    { empId: "E1004", name: "유관순", title: "연구원", dept: "백엔드개발팀", email: "gsyu@example.com" },
    { empId: "E1005", name: "김철수", title: "선임", dept: "보안운영팀", email: "cskim@example.com" },
    { empId: "E1006", name: "박영희", title: "책임", dept: "UI/UX디자인팀", email: "yhpark@example.com" },
    { empId: "E1007", name: "정도전", title: "수석", dept: "시스템아키텍처팀", email: "djjeong@example.com" },
    { empId: "E1008", name: "최영", title: "팀장", dept: "플랫폼개발팀", email: "ychoi@example.com" },
    { empId: "E1009", name: "신사임당", title: "수석", dept: "UI/UX기획팀", email: "sdshin@example.com" },
    { empId: "E1010", name: "정약용", title: "선임", dept: "데이터엔지니어링팀", email: "yjeong@example.com" }
];

scwin._targetManagerRow = -1;

scwin.fn_openManagerSearch = function(row, keyword) {
    scwin._targetManagerRow = row;
    var modal = document.getElementById("ws_mgr_modal_wrap");
    var input = document.getElementById("ws_mgr_search_input");
    if (modal) {
        modal.style.display = "flex";
        if (input) {
            input.value = keyword || "";
            input.focus();
        }
        scwin.fn_renderManagerList(keyword || "");
    }
};

scwin.fn_renderManagerList = function(keyword) {
    var tbody = document.getElementById("ws_mgr_tbl_body");
    if (!tbody) return;
    tbody.innerHTML = "";
    var kw = (keyword || "").toLowerCase().trim();

    var filtered = scwin.managerList.filter(function(emp) {
        return !kw || 
               emp.name.toLowerCase().includes(kw) || 
               emp.empId.toLowerCase().includes(kw) || 
               emp.dept.toLowerCase().includes(kw) || 
               emp.title.toLowerCase().includes(kw);
    });

    if (filtered.length === 0) {
        tbody.innerHTML = '<tr><td colspan="6" style="text-align:center; padding:20px; color:#94a3b8;">검색 조건과 일치하는 담당자가 없습니다.</td></tr>';
        return;
    }

    filtered.forEach(function(emp) {
        var tr = document.createElement("tr");
        tr.style.cursor = "pointer";
        tr.innerHTML = 
            '<td style="text-align:center; padding:8px; border-bottom:1px solid #e2e8f0;">' + emp.empId + '</td>' +
            '<td style="text-align:center; padding:8px; border-bottom:1px solid #e2e8f0; font-weight:600; color:#1e293b;">' + emp.name + '</td>' +
            '<td style="text-align:center; padding:8px; border-bottom:1px solid #e2e8f0;">' + emp.title + '</td>' +
            '<td style="text-align:left; padding:8px; border-bottom:1px solid #e2e8f0;">' + emp.dept + '</td>' +
            '<td style="text-align:left; padding:8px; border-bottom:1px solid #e2e8f0; color:#64748b;">' + emp.email + '</td>' +
            '<td style="text-align:center; padding:8px; border-bottom:1px solid #e2e8f0;">' +
                '<button type="button" class="ws-btn-mgr-select" data-name="' + emp.name + '" data-title="' + emp.title + '">선택</button>' +
            '</td>';

        tr.addEventListener("dblclick", function() {
            scwin.fn_selectManager(emp.name, emp.title);
        });

        var selBtn = tr.querySelector(".ws-btn-mgr-select");
        if (selBtn) {
            selBtn.addEventListener("click", function(e) {
                e.stopPropagation();
                scwin.fn_selectManager(emp.name, emp.title);
            });
        }
        tbody.appendChild(tr);
    });
};

scwin.fn_selectManager = function(name, title) {
    if (scwin._targetManagerRow >= 0) {
        var fullName = name + " " + title;
        dlt_sample.setCellData(scwin._targetManagerRow, "userName", fullName);
    }
    scwin.fn_closeManagerSearch();
};

scwin.fn_closeManagerSearch = function() {
    var modal = document.getElementById("ws_mgr_modal_wrap");
    if (modal) modal.style.display = "none";
    scwin._targetManagerRow = -1;
};

/**
 * 플로팅 멀티체크 레이어 오픈
 */
scwin.fn_openMultiCheckLayer = function(cellDom, row, colId, selectedCodes, dataListObj) {
    var layer = document.getElementById("ws_floating_multicheck");
    if (!layer) return;

    layer.targetRow = row;
    layer.targetColId = colId;
    layer.targetDataList = dataListObj;
    layer.checkedCodeMap = {};

    for (var i = 0; i < selectedCodes.length; i++) {
        var c = selectedCodes[i];
        if (c) layer.checkedCodeMap[c] = true;
    }

    var rect = cellDom.getBoundingClientRect();
    var layerWidth = 260;
    var layerHeight = 270;
    var top = rect.bottom + 2;
    var left = rect.left;

    if (top + layerHeight > window.innerHeight && rect.top - layerHeight > 0) {
        top = rect.top - layerHeight - 2;
    }
    if (left + layerWidth > window.innerWidth) {
        left = window.innerWidth - layerWidth - 10;
    }

    layer.style.top = top + "px";
    layer.style.left = left + "px";
    layer.style.display = "block";

    var searchInput = document.getElementById("ws_multicheck_input");
    if (searchInput) {
        searchInput.value = "";
        searchInput.focus();
    }
    scwin.fn_renderCheckList("");
};

scwin.fn_renderCheckList = function(keyword) {
    var listContainer = document.getElementById("ws_multicheck_list");
    var layer = document.getElementById("ws_floating_multicheck");
    if (!listContainer || !layer) return;

    listContainer.innerHTML = "";
    var kw = (keyword || "").toLowerCase().trim();
    var checkedMap = layer.checkedCodeMap || {};

    var items = [];
    for (var code in scwin.itemCodeMap) {
        var label = scwin.itemCodeMap[code];
        if (!kw || label.toLowerCase().includes(kw) || code.includes(kw)) {
            items.push({ code: code, label: label, isChecked: !!checkedMap[code] });
        }
    }

    items.sort(function(a, b) {
        if (a.isChecked && !b.isChecked) return -1;
        if (!a.isChecked && b.isChecked) return 1;
        return a.code.localeCompare(b.code);
    });

    items.forEach(function(item) {
        var labelEl = document.createElement("label");
        labelEl.className = "ws-multicheck-item" + (item.isChecked ? " is-checked" : "");
        labelEl.innerHTML = 
            '<input type="checkbox" value="' + item.code + '" ' + (item.isChecked ? 'checked' : '') + ' />' +
            '<span>[' + item.code + '] ' + item.label + '</span>';

        var chk = labelEl.querySelector("input");
        chk.addEventListener("change", function() {
            var val = this.value;
            if (this.checked) {
                checkedMap[val] = true;
                labelEl.classList.add("is-checked");
            } else {
                delete checkedMap[val];
                labelEl.classList.remove("is-checked");
            }
        });
        listContainer.appendChild(labelEl);
    });

    if (items.length === 0) {
        listContainer.innerHTML = '<div style="padding:15px; text-align:center; color:#94a3b8;">일치하는 항목이 없습니다.</div>';
    }
};

scwin.btn_apply_onclick = function() {
    var layer = document.getElementById("ws_floating_multicheck");
    if (!layer) return;

    var finalCodes = Object.keys(layer.checkedCodeMap || {});
    var resultValue = finalCodes.join(",");
    layer.targetDataList.setCellData(layer.targetRow, layer.targetColId, resultValue);
    scwin.fn_closeMultiCheckLayer();
};

scwin.fn_closeMultiCheckLayer = function() {
    var layer = document.getElementById("ws_floating_multicheck");
    if (layer) layer.style.display = "none";
};
